INSERT INTO kn_posts (lang, slug, title, excerpt, content, status, published_at, category_id, featured_image, meta_title, meta_description, og_image)
SELECT 'fr', 'nettoyage-canape-fauteuil-tissu', 'Nettoyage de canapé et fauteuil en tissu : méthode, prix et conseils', 'Pourquoi, comment et à quel prix faire nettoyer un canapé ou un fauteuil en tissu ? Notre méthode en trois étapes, nos tarifs de 99 à 200 € et des conseils d\'entretien.', '[{"type":"text","bg":"white","html":"<p><strong>Un canapé ou un fauteuil en tissu, c\'est confortable… et c\'est un véritable aimant à poussière, à acariens et à taches.</strong> On y dort, on y mange, on y joue avec les enfants ou le chien : au fil des mois, la saleté s\'incruste dans les fibres sans que l\'on s\'en rende compte. Dans cet article, nous vous expliquons pourquoi nettoyer son canapé en tissu, comment un professionnel s\'y prend, et combien cela coûte vraiment.</p><h2 class=\\"kn-subtitle\\">L\'essentiel en un coup d\'œil</h2><ul class=\\"kn-checklist\\"><li><strong>Tarif :</strong> de 99 € (1 à 3 places) à 200 € (8 places et plus).</li><li><strong>Où :</strong> directement chez vous, en province de Liège, à Namur et dans le Luxembourg belge.</li><li><strong>Fréquence conseillée :</strong> un nettoyage en profondeur par an, plus si vous avez enfants ou animaux.</li><li><strong>Paiement :</strong> uniquement après la prestation.</li></ul>","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"cream","eyebrow":"POURQUOI NETTOYER","h2":"Pourquoi faire nettoyer votre canapé en tissu ?","intro":"Le canapé est le cœur du salon, mais le tissu retient tout : poussière, allergènes, poils, transpiration, miettes et taches. Un nettoyage professionnel change vraiment la donne.","columns":"2","items":[{"title":"Une durée de vie plus longue","desc":"En retirant la saleté incrustée, on évite l\'usure prématurée des fibres et du rembourrage."},{"title":"Un air intérieur plus sain","desc":"Poussière et allergènes accumulés dans le tissu sont éliminés, un vrai plus pour les personnes sensibles."},{"title":"Fraîcheur et aspect d\'origine","desc":"Auréoles, taches et odeurs disparaissent, et les couleurs reprennent de l\'éclat."},{"title":"Un investissement protégé","desc":"Un canapé entretenu garde son aspect et sa valeur bien plus longtemps."}],"visible":["desktop","tablet","mobile"]},{"type":"text","bg":"white","html":"<h2 class=\\"kn-subtitle\\">Les signes qu\'il est temps de nettoyer votre canapé</h2><p>Pas besoin d\'attendre une grosse tache. Voici les signaux qui doivent vous alerter :</p><ul class=\\"kn-checklist\\"><li>Des <strong>taches ou auréoles</strong> visibles, même anciennes.</li><li>Une <strong>odeur persistante</strong> (animaux, tabac, humidité, transpiration).</li><li>Un tissu <strong>terne, gris ou qui brille</strong> aux endroits où l\'on s\'assoit.</li><li>Des <strong>éternuements ou démangeaisons</strong> quand vous vous installez dessus.</li><li>Plus d\'un an écoulé depuis le <strong>dernier nettoyage en profondeur</strong>.</li></ul>","visible":["desktop","tablet","mobile"]},{"type":"how","bg":"alt","eyebrow":"NOTRE MÉTHODE","h2":"Notre méthodologie de nettoyage pour vos canapés en tissus","steps":[{"title":"Évaluation","body":"Nous examinons le tissu, l\'état général et les taches : graisse, vin, encre, sang, moisissure, urine ou transpiration. Chaque tache demande un produit et une technique adaptés."},{"title":"Préparation","body":"Nous protégeons le sol et les meubles à proximité, puis choisissons les produits adaptés à chaque type de tissu pour ne pas abîmer fibres et couleurs."},{"title":"Nettoyage","body":"Avec un équipement professionnel, nous éliminons taches visibles, saleté incrustée et allergènes, puis désinfectons en profondeur. Le canapé est vite réutilisable."}],"visible":["desktop","tablet","mobile"]},{"type":"quote","bg":"cream","text":"Mon canapé en tissu aurait bien besoin d\'un nettoyage en profondeur.","author":"","role":"La phrase que l\'on se dit tous un jour","visible":["desktop","tablet","mobile"]},{"type":"domicile-vs-atelier","bg":"white","eyebrow":"TISSUS ET TACHES","h2":"Quels tissus, quelles taches : ce que le nettoyage peut (ou non) faire","intro":"Nous nettoyons tous les types de canapés : tissu, microfibre, velours, cuir, Alcantara, canapés d\'angle, convertibles, panoramiques, méridiennes et relax.","steps":[{"icon":"sparkles","label":"Tissu"},{"icon":"sparkles","label":"Microfibre"},{"icon":"sparkles","label":"Velours"},{"icon":"sparkles","label":"Alcantara"},{"icon":"sparkles","label":"Cuir"}],"home_title":"Ce qui s\'élimine très bien","home_icon":"check-big","home_items":[{"icon":"check","label":"Taches du quotidien (café, graisse, boissons)"},{"icon":"check","label":"Poussière, acariens et allergènes"},{"icon":"check","label":"Odeurs d\'animaux, de tabac, de transpiration"},{"icon":"check","label":"Poils d\'animaux"},{"icon":"check","label":"Auréoles et traces d\'usage"}],"workshop_title":"Les cas plus délicats","workshop_icon":"shield","workshop_items":[{"icon":"x","label":"Taches très anciennes ou incrustées (résultat à confirmer)"},{"icon":"x","label":"Décolorations dues au soleil"},{"icon":"x","label":"Tissu déchiré ou usé jusqu\'à la trame"}],"workshop_note":"Lors de l\'évaluation, nous vous indiquons honnêtement ce qui peut être amélioré avant de commencer.","visible":["desktop","tablet","mobile"]},{"type":"pricing","bg":"alt","eyebrow":"TARIFS","h2":"Nettoyage de canapés : prix clairs et sans surprise","intro":"Le tarif dépend uniquement de la taille du canapé. Il comprend le nettoyage en profondeur et le traitement des taches du quotidien, des odeurs, des poils d\'animaux et de la poussière.","items":[{"label":"Canapé 1 à 3 places","price":"99 €"},{"label":"Canapé 4 à 5 places","price":"140 €"},{"label":"Canapé 6 à 8 places","price":"170 €"},{"label":"Canapé 8 places et +","price":"200 €"}],"note":"Déplacement gratuit dans un rayon de 20 km autour de notre bureau de Seraing (Liège). Au-delà, un supplément de 0,50 € par km peut s\'appliquer.","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"white","eyebrow":"LES AVANTAGES","h2":"Les avantages du nettoyage professionnel","intro":"Les produits du commerce ne remplacent pas le savoir-faire et le matériel d\'un professionnel. Voici ce que vous gagnez en nous confiant votre canapé.","columns":"1","items":[{"title":"Expertise","desc":"Des techniciens formés, qui utilisent des produits adaptés à chaque tissu."},{"title":"Équipement de pointe","desc":"Des machines de nettoyage professionnelles qui extraient la saleté en profondeur sans détremper."},{"title":"Satisfaction garantie","desc":"Un service de qualité avec un excellent rapport qualité-prix, et un paiement uniquement après la prestation."}],"visible":["desktop","tablet","mobile"]},{"type":"quote","bg":"white","text":"Canapé impeccable à l\'intérieur comme à l\'extérieur. Rapide et professionnel.","author":"Stella M.","role":"Cliente Keepnew","visible":["desktop","tablet","mobile"]},{"type":"quote","bg":"white","text":"Les taches ont disparu et le canapé a l\'air neuf.","author":"Arnaud T.","role":"Client Keepnew","visible":["desktop","tablet","mobile"]},{"type":"text","bg":"white","html":"<h2 class=\\"kn-subtitle\\">Comment entretenir son canapé en tissu entre deux nettoyages</h2><p>Quelques gestes simples prolongent l\'effet d\'un nettoyage professionnel :</p><ul class=\\"kn-checklist\\"><li><strong>Aspirez chaque semaine</strong> avec le petit embout, y compris entre les coussins et le long des coutures.</li><li><strong>Traitez une tache tout de suite</strong> : tamponnez avec un linge propre et peu d\'eau, du bord vers le centre, sans frotter.</li><li><strong>Évitez l\'excès d\'eau</strong> : un tissu détrempé sèche mal et peut laisser des auréoles ou des odeurs.</li><li><strong>Retournez et aérez les coussins</strong> pour répartir l\'usure.</li><li><strong>Éloignez le canapé du soleil direct</strong>, qui décolore certains tissus.</li><li><strong>Protégez-le</strong> avec un plaid ou un jeté si les animaux y montent.</li></ul><p>Ces gestes réduisent les taches, mais ils ne remplacent pas un nettoyage en profondeur : celui-ci extrait la saleté qui s\'est logée dans le rembourrage.</p>","visible":["desktop","tablet","mobile"]},{"type":"zone","bg":"blue","eyebrow":"À DOMICILE","h2":"Profitez d\'un nettoyage de canapé en tissu professionnel à domicile","desc":"Nous venons chez vous : pas besoin de transporter votre canapé. Nous intervenons dans la province de Liège, à Namur et dans la province du Luxembourg, et dans bien d\'autres communes : contactez-nous pour vérifier la disponibilité.","pills":[{"label":"Amay"},{"label":"Anthisnes"},{"label":"Ans"},{"label":"Awans"},{"label":"Aywaille"},{"label":"Bassenge"},{"label":"Berloz"},{"label":"Beyne-Heusay"},{"label":"Blegny"},{"label":"Braives"},{"label":"Burdinne"},{"label":"Chaudfontaine"},{"label":"Clavier"},{"label":"Comblain-au-Pont"},{"label":"Crisnée"},{"label":"Dalhem"},{"label":"Donceel"},{"label":"Engis"},{"label":"Esneux"},{"label":"Faimes"},{"label":"Ferrières"},{"label":"Fexhe-le-Haut-Clocher"},{"label":"Flémalle"},{"label":"Fléron"},{"label":"Geer"},{"label":"Grâce-Hollogne"},{"label":"Hannut"},{"label":"Hamoir"},{"label":"Herstal"},{"label":"Héron"},{"label":"Huy"},{"label":"Juprelle"},{"label":"Liège"},{"label":"Lincent"},{"label":"Marchin"},{"label":"Modave"},{"label":"Nandrin"},{"label":"Neupré"},{"label":"Oreye"},{"label":"Ouffet"},{"label":"Oupeye"},{"label":"Remicourt"},{"label":"Saint-Georges-sur-Meuse"},{"label":"Saint-Nicolas"},{"label":"Seraing"},{"label":"Soumagne"},{"label":"Sprimont"},{"label":"Tinlot"},{"label":"Trooz"},{"label":"Verlaine"},{"label":"Villers-le-Bouillet"},{"label":"Visé"},{"label":"Waremme"},{"label":"Wanze"},{"label":"Wasseiges"}],"visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"rose","h2":"Carte de fidélité : débloquez des étoiles à chaque nettoyage","body":"<p>Chaque prestation vous rapproche d\'une remise sur la suivante. Prenez rendez-vous dès maintenant et commencez à cumuler vos étoiles.</p>","cta_label":"Prenez RDV en ligne dès maintenant","cta_style":"primary","cta_align":"left","visible":["desktop","tablet","mobile"]},{"type":"accordion","bg":"white","eyebrow":"FAQ","h2":"Vos questions sur le nettoyage de canapé en tissu","items":[{"q":"Combien de temps dure l\'intervention ?","a":"Comptez en général de 1 à 2 heures selon la taille du canapé et l\'état du tissu."},{"q":"Combien de temps faut-il pour que le canapé sèche ?","a":"Le canapé est utilisable rapidement ; un séchage complet prend quelques heures selon le tissu et la ventilation de la pièce."},{"q":"Les taches anciennes peuvent-elles partir ?","a":"Dans la plupart des cas, oui. Certaines taches très anciennes ou incrustées peuvent rester légèrement visibles ; nous vous le disons avant de commencer."},{"q":"Les odeurs d\'animaux ou de tabac sont-elles éliminées ?","a":"Le nettoyage en profondeur et la désinfection éliminent la plupart des odeurs à la source."},{"q":"Combien coûte le nettoyage selon la taille du canapé ?","a":"De 99 € pour 1 à 3 places à 200 € pour 8 places et plus. Le déplacement est gratuit dans un rayon de 20 km autour de Seraing."},{"q":"Faut-il être présent pendant le nettoyage ?","a":"Il est préférable d\'être présent au début pour valider le diagnostic et à la fin pour constater le résultat."},{"q":"Quand dois-je payer ?","a":"Vous payez uniquement après la prestation."}],"visible":["desktop","tablet","mobile"]},{"type":"reviews","bg":"cream","eyebrow":"ILS NOUS FONT CONFIANCE","h2":"Ce que disent nos clients","visible":["desktop","tablet","mobile"]},{"type":"cta-final","bg":"blue","eyebrow":"RÉSERVATION EN LIGNE","title":"Prêt à redonner vie à <span class=\\"hl-inverse\\">votre canapé</span> ?","cta_title":"Prenez RDV en ligne","phone":"+32 (0)4 55 13 84 19","visible":["desktop","tablet","mobile"]}]', 'draft', NULL, (SELECT id FROM kn_categories WHERE slug = 'conseils-entretien' AND lang = 'fr' LIMIT 1), NULL, 'Nettoyage canapé et fauteuil en tissu : méthode, prix | Keepnew', 'Nettoyage professionnel de canapé et fauteuil en tissu à domicile (Liège, Namur, Luxembourg) : méthode, tarifs de 99 à 200 €, conseils d\'entretien et FAQ.', NULL
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM kn_posts WHERE slug = 'nettoyage-canape-fauteuil-tissu' AND lang = 'fr');
